var D=[{"alt":[],"cls":"Alchemist (2014)","name":"Amorist (2014)","src":"tvss14","arr":[[3,"Armorist","Amorists brew potions that stir strong feelings, love potions above all, and craft pheromone bombs that can soften even terrible monsters."],[3,"Bonus Proficiencies","You gain proficiency in Deception and Persuasion."],[3,"Pheromone Bomb","Bomb formula: Pheromone Bomb. The Bomb deals no damage and uses a Wisdom save. The target, and each creature in the blast that fails its save, is Charmed by you until the end of its turn or until it takes damage."],[6,"Magnetic Personality","Add your Intelligence modifier to your Charisma checks."],[10,"Alchemical Perfume","When a hostile creature within 5 feet makes an attack roll against you, it makes a Wisdom save against your Bomb save DC or has Disadvantage on the roll. A creature that succeeds is immune for 24 hours. Creatures immune to Charm succeed automatically."],[18,"Alchemical Romance","During a Long Rest you can spend 4 reagent dice to brew a Potion of True Love. It works like a Philter of Love, but you pick the creature the drinker sees as its true love, provided the drinker knows that creature or meets it within 24 hours. The effect lasts until you brew a new True Love potion or Remove Curse or similar magic ends it. When it ends, the drinker feels total disgust for that creature and can never love it again."]],"full":{"Amorist (2014)|Armorist":"Amorists brew potions that stir strong feelings, love potions above all, and craft pheromone bombs that can soften even terrible monsters.","Amorist (2014)|Bonus Proficiencies":"You gain proficiency in Deception and Persuasion.","Amorist (2014)|Pheromone Bomb":"Bomb formula: Pheromone Bomb. The Bomb deals no damage and uses a Wisdom save. The target, and each creature in the blast that fails its save, is Charmed by you until the end of its turn or until it takes damage.","Amorist (2014)|Magnetic Personality":"Add your Intelligence modifier to your Charisma checks.","Amorist (2014)|Alchemical Perfume":"When a hostile creature within 5 feet makes an attack roll against you, it makes a Wisdom save against your Bomb save DC or has Disadvantage on the roll. A creature that succeeds is immune for 24 hours. Creatures immune to Charm succeed automatically.","Amorist (2014)|Alchemical Romance":"During a Long Rest you can spend 4 reagent dice to brew a Potion of True Love. It works like a Philter of Love, but you pick the creature the drinker sees as its true love, provided the drinker knows that creature or meets it within 24 hours. The effect lasts until you brew a new True Love potion or Remove Curse or similar magic ends it. When it ends, the drinker feels total disgust for that creature and can never love it again."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[2,"Bonus Proficiencies",{"skills":["Deception","Persuasion"]}],[6,"Magnetic Personality",{"notes":[["Note","Magnetic Personality: add your Intelligence modifier to Charisma checks"]]}]],"spab":""},{"alt":[],"cls":"Alchemist (2014)","name":"Apothecary (2014)","src":"tvss14","arr":[[3,"Bonus Proficiencies","You gain proficiency in Medicine."],[3,"Formula: Painkiller Bomb","Bomb formula: Painkiller Bomb. The Bomb deals no damage. Each creature in the blast gains Temporary Hit Points equal to 1d8 plus half your Alchemist level until the end of your next turn. It has no effect on Constructs and Undead."],[6,"Potion Toss","As an action you can hurl a potion at a willing creature within 20 feet. It gains the benefit as if it had drunk the potion."],[10,"Self-Medication","When you drink a potion that restores HP (even at full HP), you have Advantage on saving throws until the end of your next turn."],[18,"Alchemical Resurrection","As an action you can mix 500 GP of diamond dust into a Potion of Superior or Supreme Healing to make a Potion of Raise Dead. Pouring it as an action on a Humanoid corpse dead no longer than 10 days casts Raise Dead on it."]],"full":{"Apothecary (2014)|Bonus Proficiencies":"You gain proficiency in Medicine.","Apothecary (2014)|Formula: Painkiller Bomb":"Bomb formula: Painkiller Bomb. The Bomb deals no damage. Each creature in the blast gains Temporary Hit Points equal to 1d8 plus half your Alchemist level until the end of your next turn. It has no effect on Constructs and Undead.","Apothecary (2014)|Potion Toss":"As an action you can hurl a potion at a willing creature within 20 feet. It gains the benefit as if it had drunk the potion.","Apothecary (2014)|Self-Medication":"When you drink a potion that restores HP (even at full HP), you have Advantage on saving throws until the end of your next turn.","Apothecary (2014)|Alchemical Resurrection":"As an action you can mix 500 GP of diamond dust into a Potion of Superior or Supreme Healing to make a Potion of Raise Dead. Pouring it as an action on a Humanoid corpse dead no longer than 10 days casts Raise Dead on it."},"auto":[],"lu":[],"acts":{"sub|Apothecary (2014)|Potion Toss":[["action",""]]},"cantrips":[],"pick":[],"fx":[[2,"Bonus Proficiencies",{"skills":["Medicine"]}],[10,"Self-Medication",{"notes":[["Note","Self-Medication: after drinking a healing potion, Advantage on saving throws until the end of your next turn"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Bloodwrath Guardian","src":"tvss14","arr":[[3,"Feral Trance","Bonus Action: fall into a battle trance for 1 minute. You have Advantage on Strength checks and Strength saving throws, your Speed rises by 10 feet, and you have Advantage on melee weapon attacks made with Strength against a creature you have marked. Attacks against you also have Advantage. The trance ends early if you fall Unconscious, or if your turn ends and you neither attacked a hostile creature nor took damage since your last turn. You can end it as a Bonus Action. Short or Long Rest to use it again."],[6,"Predator's Scent","A creature you have marked stays marked for up to 24 hours, even out of your sight. While it is marked you know its direction and distance, as long as it is on your plane."],[13,"Evasion","When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Form of the Primal Beast","Action: for 1 minute you turn into a hunched shape of fur and shadow. You gain the benefits of Feral Trance and Temporary Hit Points equal to twice your level. When you hit with a melee weapon attack you can give the target a bleeding wound (not Constructs, Oozes or Undead). At the start of each of its turns a creature loses 1d8 HP for each bleeding wound unless it uses an action to staunch them, and it cannot regain HP while bleeding. A creature can have wounds up to your Proficiency Bonus. Long Rest to use it again."]],"full":{"Bloodwrath Guardian|Feral Trance":"Bonus Action: fall into a battle trance for 1 minute. You have Advantage on Strength checks and Strength saving throws, your Speed rises by 10 feet, and you have Advantage on melee weapon attacks made with Strength against a creature you have marked. Attacks against you also have Advantage. The trance ends early if you fall Unconscious, or if your turn ends and you neither attacked a hostile creature nor took damage since your last turn. You can end it as a Bonus Action. Short or Long Rest to use it again.","Bloodwrath Guardian|Predator's Scent":"A creature you have marked stays marked for up to 24 hours, even out of your sight. While it is marked you know its direction and distance, as long as it is on your plane.","Bloodwrath Guardian|Evasion":"When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure.","Bloodwrath Guardian|Form of the Primal Beast":"Action: for 1 minute you turn into a hunched shape of fur and shadow. You gain the benefits of Feral Trance and Temporary Hit Points equal to twice your level. When you hit with a melee weapon attack you can give the target a bleeding wound (not Constructs, Oozes or Undead). At the start of each of its turns a creature loses 1d8 HP for each bleeding wound unless it uses an action to staunch them, and it cannot regain HP while bleeding. A creature can have wounds up to your Proficiency Bonus. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Bloodwrath Guardian","feature":"Feral Trance","n":"Feral Trance","lvl":3,"max":1,"reset":"short","tag":"Bonus Action. 1 minute"},{"src":"sub","owner":"Bloodwrath Guardian","feature":"Form of the Primal Beast","n":"Form of the Primal Beast","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Bloodwrath Guardian|Feral Trance":[["bonus",""]],"sub|Bloodwrath Guardian|Form of the Primal Beast":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Feral Trance",{"notes":[["Note","Feral Trance: Advantage on Strength checks and saves, Speed +10 ft, Advantage on Strength melee attacks against your marked creature, attacks against you have Advantage"]]}],[6,"Predator's Scent",{"notes":[["Note","Predator's Scent: marked creature stays marked 24 hours and you know its direction and distance on the same plane"]]}],[13,"Evasion",{"notes":[["Note","Evasion: a successful Dexterity save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Carrion King (2014)","src":"tvss14","arr":[[3,"Gnawing Mark","Vermin swarm over a creature you mark. While it is marked, it rolls a d4 and subtracts the result from each attack roll and ability check it makes."],[6,"Infested","Vermin fill your clothes and gear. When a creature within 5 feet hits you with an attack, they strike back for 1d6 Piercing damage. On each later attack that creature makes before the end of its turn, it rolls a d4 and subtracts the result from the attack roll."],[13,"Evasion","When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Lord of the Flies","Action: call up a huge swarm of flies and rodents around you for 1 minute. A 10-foot-radius sphere centered on you is heavily obscured. Each creature you choose has Disadvantage on attack rolls and ability checks while in it, and takes 6d4 Piercing damage when it first enters on a turn or starts its turn there. Long Rest to use it again."]],"full":{"Carrion King (2014)|Gnawing Mark":"Vermin swarm over a creature you mark. While it is marked, it rolls a d4 and subtracts the result from each attack roll and ability check it makes.","Carrion King (2014)|Infested":"Vermin fill your clothes and gear. When a creature within 5 feet hits you with an attack, they strike back for 1d6 Piercing damage. On each later attack that creature makes before the end of its turn, it rolls a d4 and subtracts the result from the attack roll.","Carrion King (2014)|Evasion":"When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure.","Carrion King (2014)|Lord of the Flies":"Action: call up a huge swarm of flies and rodents around you for 1 minute. A 10-foot-radius sphere centered on you is heavily obscured. Each creature you choose has Disadvantage on attack rolls and ability checks while in it, and takes 6d4 Piercing damage when it first enters on a turn or starts its turn there. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Carrion King (2014)","feature":"Lord of the Flies","n":"Lord of the Flies","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Carrion King (2014)|Lord of the Flies":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Gnawing Mark",{"notes":[["Note","Gnawing Mark: a marked creature subtracts a d4 from its attack rolls and ability checks"]]}],[6,"Infested",{"notes":[["Note","Infested: a creature that hits you in melee takes 1d6 Piercing, then subtracts a d4 from its later attacks that turn"]]}],[13,"Evasion",{"notes":[["Note","Evasion: a successful Dexterity save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Demon Banner","src":"tvss14","arr":[[3,"Maneuver: Abyssal Rebuke","When a creature you can see within 60 feet damages you, you can use your Reaction and spend a battle die. It makes a Dexterity save. On a failure it takes Fire damage equal to the die plus your Charisma modifier, or half on a success."],[7,"Demon's Sight","You gain your demon's Darkvision out to 120 feet. You and the demon can see normally in magical darkness."],[13,"Abyssal Arcana","You can use your demon's Innate Spellcasting trait even when you are not transformed."],[17,"One with the Abyss","Your bond with the demon is unbreakable. You and it share a pool of HP, your maximum plus the demon's. You both have the higher AC of the two forms. You can use the demon's flying Speed even when not transformed."]],"full":{"Demon Banner|Maneuver: Abyssal Rebuke":"When a creature you can see within 60 feet damages you, you can use your Reaction and spend a battle die. It makes a Dexterity save. On a failure it takes Fire damage equal to the die plus your Charisma modifier, or half on a success.","Demon Banner|Demon's Sight":"You gain your demon's Darkvision out to 120 feet. You and the demon can see normally in magical darkness.","Demon Banner|Abyssal Arcana":"You can use your demon's Innate Spellcasting trait even when you are not transformed.","Demon Banner|One with the Abyss":"Your bond with the demon is unbreakable. You and it share a pool of HP, your maximum plus the demon's. You both have the higher AC of the two forms. You can use the demon's flying Speed even when not transformed."},"auto":[],"lu":[],"acts":{"sub|Demon Banner|Maneuver: Abyssal Rebuke":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[7,"Demon's Sight",{"senses":[["Darkvision",120,"Also see in magical darkness"]]}]],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Dragon Banner (2014)","src":"tvss14","arr":[[3,"Bonus Battle Dice","Your total number of battle dice rises by 1."],[3,"Maneuver: Cleave","Once on each of your turns, when you reduce a hostile creature to 0 HP or score a critical hit with a melee weapon attack, spend a battle die to move up to 15 feet and make another melee weapon attack as part of the same action. On a hit, add the die to the damage."],[7,"Maneuver: Wade Into Battle","Spend a battle die to take the Dash or Disengage action as a Bonus Action on your turn."],[13,"Maneuver: Fury Attack","When you take the Attack action on your turn, spend a battle die as a Bonus Action to unleash a barrage. Make up to three melee weapon attacks as part of the Attack action instead of one, each against a different creature."],[17,"Vicious Focus","When you reduce a hostile creature to 0 HP or score a critical hit with a melee weapon attack, you enter a battle trance for 1 minute. Your weapon attacks score a critical hit on a 19 or 20. Each time you drop another hostile creature to 0 HP or score another critical hit, the range widens: first 18-20, then 17-20, then 16-20. It ends early if you fall Unconscious."]],"full":{"Dragon Banner (2014)|Bonus Battle Dice":"Your total number of battle dice rises by 1.","Dragon Banner (2014)|Maneuver: Cleave":"Once on each of your turns, when you reduce a hostile creature to 0 HP or score a critical hit with a melee weapon attack, spend a battle die to move up to 15 feet and make another melee weapon attack as part of the same action. On a hit, add the die to the damage.","Dragon Banner (2014)|Maneuver: Wade Into Battle":"Spend a battle die to take the Dash or Disengage action as a Bonus Action on your turn.","Dragon Banner (2014)|Maneuver: Fury Attack":"When you take the Attack action on your turn, spend a battle die as a Bonus Action to unleash a barrage. Make up to three melee weapon attacks as part of the Attack action instead of one, each against a different creature.","Dragon Banner (2014)|Vicious Focus":"When you reduce a hostile creature to 0 HP or score a critical hit with a melee weapon attack, you enter a battle trance for 1 minute. Your weapon attacks score a critical hit on a 19 or 20. Each time you drop another hostile creature to 0 HP or score another critical hit, the range widens: first 18-20, then 17-20, then 16-20. It ends early if you fall Unconscious."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[3,"Bonus Battle Dice",{"notes":[["Note","Bonus Battle Dice: you have one more battle die than the Captain table shows"]]}]],"spab":""},{"alt":[],"cls":"Alchemist (2014)","name":"Dynamo Engineer (2014)","src":"tvss14","arr":[[3,"Spectrum Analyzer","You build a monocle that shows magical auras. You can cast Detect Magic once with no slot or components. Short or Long Rest to use it again."],[3,"Spellcasting","You cast Wizard spells by storing energy in handheld spell dynamos, each holding one spell slot. The Dynamo Engineer Spellcasting table gives your dynamos and their slot level, which is the same for all. To cast a level 1+ Wizard spell, you expend a dynamo. A Long Rest restores them all. **Preparing.** When you finish a Long Rest you configure each dynamo for one Wizard spell you know, and a dynamo casts only that spell. After a Short or Long Rest you can reconfigure unexpended dynamos. **Spells known.** You know three level 1 Wizard spells, two of them Evocation or Transmutation. The table shows when you learn more. Each must be Evocation or Transmutation and of a level you have slots for, except those learned at levels 8, 14 and 20, which can be from any school. When you gain an Alchemist level you can swap one spell by the same rule. **Spellcasting ability.** Intelligence. Use your Bomb save DC as the save DC of your Wizard spells and your Intelligence modifier for spell attacks."],[6,"Formula: Arcano Bomb","Bomb formula: Arcano Bomb. Add an unexpended dynamo to your Bomb, which spends its slot. It deals Force damage instead of Fire, its dice are d12s, and it deals one extra die as if a reagent die were added."],[10,"Counter-Discharge","When a creature you can see casts a spell that affects you, you can use your Reaction and expend a dynamo to release disruptive energy. You have Advantage on the saving throw against the spell, and Resistance to its damage. Long Rest to use it again."],[18,"Arcane Recycler","When you miss with an Arcano Bomb, you can recycle the slot stored in the dynamo and move it into one of your empty dynamos."]],"full":{"Dynamo Engineer (2014)|Spectrum Analyzer":"You build a monocle that shows magical auras. You can cast Detect Magic once with no slot or components. Short or Long Rest to use it again.","Dynamo Engineer (2014)|Spellcasting":"You cast Wizard spells by storing energy in handheld spell dynamos, each holding one spell slot. The Dynamo Engineer Spellcasting table gives your dynamos and their slot level, which is the same for all. To cast a level 1+ Wizard spell, you expend a dynamo. A Long Rest restores them all. **Preparing.** When you finish a Long Rest you configure each dynamo for one Wizard spell you know, and a dynamo casts only that spell. After a Short or Long Rest you can reconfigure unexpended dynamos. **Spells known.** You know three level 1 Wizard spells, two of them Evocation or Transmutation. The table shows when you learn more. Each must be Evocation or Transmutation and of a level you have slots for, except those learned at levels 8, 14 and 20, which can be from any school. When you gain an Alchemist level you can swap one spell by the same rule. **Spellcasting ability.** Intelligence. Use your Bomb save DC as the save DC of your Wizard spells and your Intelligence modifier for spell attacks.","Dynamo Engineer (2014)|Formula: Arcano Bomb":"Bomb formula: Arcano Bomb. Add an unexpended dynamo to your Bomb, which spends its slot. It deals Force damage instead of Fire, its dice are d12s, and it deals one extra die as if a reagent die were added.","Dynamo Engineer (2014)|Counter-Discharge":"When a creature you can see casts a spell that affects you, you can use your Reaction and expend a dynamo to release disruptive energy. You have Advantage on the saving throw against the spell, and Resistance to its damage. Long Rest to use it again.","Dynamo Engineer (2014)|Arcane Recycler":"When you miss with an Arcano Bomb, you can recycle the slot stored in the dynamo and move it into one of your empty dynamos."},"auto":[],"lu":[{"src":"sub","owner":"Dynamo Engineer (2014)","feature":"Spectrum Analyzer","n":"Spectrum Analyzer","lvl":3,"max":1,"reset":"short","tag":"Detect Magic"},{"src":"sub","owner":"Dynamo Engineer (2014)","feature":"Counter-Discharge","n":"Counter-Discharge","lvl":10,"max":1,"reset":"long","tag":"Reaction"}],"acts":{"sub|Dynamo Engineer (2014)|Counter-Discharge":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[10,"Counter-Discharge",{"notes":[["Note","Counter-Discharge: Reaction and a dynamo give Advantage on the save and Resistance to damage from a spell that affects you"]]}]],"spab":"INT"},{"alt":[],"cls":"Captain (2014)","name":"Eagle Banner (2014)","src":"tvss14","arr":[[3,"Maneuver: Eagle Shot","When you make a ranged weapon attack roll against a creature, you can use your Bonus Action and spend a battle die to add it to the roll, before or after rolling but before the GM says whether it hits."],[7,"Vantage Point","You have a Climb Speed equal to your Speed. Climbing at half speed, you can scale difficult surfaces, such as slippery vertical walls, without an ability check."],[13,"Close-Quarters Shooting","A hostile creature within 5 feet does not impose Disadvantage on your ranged attack rolls, or on those of friendly creatures within 15 feet of you."],[17,"Scatter Shot","As an action you launch a volley. Make a ranged weapon attack against any number of creatures you choose in a 15-foot cone, with a separate roll for each. If you target only one creature, a hit deals one extra weapon damage die."]],"full":{"Eagle Banner (2014)|Maneuver: Eagle Shot":"When you make a ranged weapon attack roll against a creature, you can use your Bonus Action and spend a battle die to add it to the roll, before or after rolling but before the GM says whether it hits.","Eagle Banner (2014)|Vantage Point":"You have a Climb Speed equal to your Speed. Climbing at half speed, you can scale difficult surfaces, such as slippery vertical walls, without an ability check.","Eagle Banner (2014)|Close-Quarters Shooting":"A hostile creature within 5 feet does not impose Disadvantage on your ranged attack rolls, or on those of friendly creatures within 15 feet of you.","Eagle Banner (2014)|Scatter Shot":"As an action you launch a volley. Make a ranged weapon attack against any number of creatures you choose in a 15-foot cone, with a separate roll for each. If you target only one creature, a hit deals one extra weapon damage die."},"auto":[],"lu":[],"acts":{"sub|Eagle Banner (2014)|Scatter Shot":[["action",""]]},"cantrips":[],"pick":[],"fx":[[7,"Vantage Point",{"notes":[["Note","Vantage Point: Climb Speed equal to your Speed"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Fey Trailblazer","src":"tvss14","arr":[[3,"Alluring Mark","When you use Warden's Mark, you can try an Alluring Mark. The target makes a Wisdom saving throw (DC 8 + your Proficiency Bonus + your Constitution modifier). On a failure, instead of the usual effect, it is Charmed by you while it is within 5 feet of you. The mark ends early if you damage the creature."],[6,"Misty Jaunt","You can spend all of your movement to teleport up to half your Speed."],[13,"Spell Resistance","You have Advantage on saving throws against spells."],[20,"Archfey of Majesty","Action: for 1 minute you embody the grace of the archfey. When a creature tries to attack you, it makes a Wisdom saving throw (DC 8 + your Proficiency Bonus + your Constitution modifier). On a failure its attack misses. On a success it is immune to this effect for 24 hours. As a Bonus Action you can teleport up to 30 feet to an unoccupied space you can see. Long Rest to use it again."]],"full":{"Fey Trailblazer|Alluring Mark":"When you use Warden's Mark, you can try an Alluring Mark. The target makes a Wisdom saving throw (DC 8 + your Proficiency Bonus + your Constitution modifier). On a failure, instead of the usual effect, it is Charmed by you while it is within 5 feet of you. The mark ends early if you damage the creature.","Fey Trailblazer|Misty Jaunt":"You can spend all of your movement to teleport up to half your Speed.","Fey Trailblazer|Spell Resistance":"You have Advantage on saving throws against spells.","Fey Trailblazer|Archfey of Majesty":"Action: for 1 minute you embody the grace of the archfey. When a creature tries to attack you, it makes a Wisdom saving throw (DC 8 + your Proficiency Bonus + your Constitution modifier). On a failure its attack misses. On a success it is immune to this effect for 24 hours. As a Bonus Action you can teleport up to 30 feet to an unoccupied space you can see. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Fey Trailblazer","feature":"Archfey of Majesty","n":"Archfey of Majesty","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Fey Trailblazer|Archfey of Majesty":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Alluring Mark",{"notes":[["Note","Alluring Mark: Warden's Mark can Charm the target (Wisdom save, DC 8 + PB + CON) while it is within 5 feet of you"]]}],[6,"Misty Jaunt",{"notes":[["Note","Misty Jaunt: spend all movement to teleport up to half your Speed"]]}]],"spab":"","gx":[{"l":13,"n":"Spell Resistance","advOn":["saving throws against spells"]}]},{"alt":[],"cls":"Warden (2014)","name":"Godsworn (2014)","src":"tvss14","arr":[[3,"Anointed Mark","Warden's Mark can target a friendly creature within 30 feet. While it stays marked, it is under the effects of the Bless spell."],[3,"Bonus Proficiencies","You gain proficiency in Medicine and Religion. If you already have one of them, your Proficiency Bonus is doubled for ability checks with it."],[6,"Holy Allies","Action: cast Spirit Guardians with no spell slot (DC 8 + your Proficiency Bonus + your Strength modifier). Long Rest to use it again."],[13,"Mettle","When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Sainted Mantle","Bonus Action: wrap yourself in divine light for 1 minute. While conscious you regain 5 HP at the start of each of your turns, or 10 HP if you have less than half your HP at that moment. Long Rest to use it again."]],"full":{"Godsworn (2014)|Anointed Mark":"Warden's Mark can target a friendly creature within 30 feet. While it stays marked, it is under the effects of the Bless spell.","Godsworn (2014)|Bonus Proficiencies":"You gain proficiency in Medicine and Religion. If you already have one of them, your Proficiency Bonus is doubled for ability checks with it.","Godsworn (2014)|Holy Allies":"Action: cast Spirit Guardians with no spell slot (DC 8 + your Proficiency Bonus + your Strength modifier). Long Rest to use it again.","Godsworn (2014)|Mettle":"When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure.","Godsworn (2014)|Sainted Mantle":"Bonus Action: wrap yourself in divine light for 1 minute. While conscious you regain 5 HP at the start of each of your turns, or 10 HP if you have less than half your HP at that moment. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Godsworn (2014)","feature":"Holy Allies","n":"Holy Allies","lvl":6,"max":1,"reset":"long","tag":"Spirit Guardians, no slot"},{"src":"sub","owner":"Godsworn (2014)","feature":"Sainted Mantle","n":"Sainted Mantle","lvl":20,"max":1,"reset":"long","tag":"Bonus Action. 1 minute"}],"acts":{"sub|Godsworn (2014)|Holy Allies":[["action",""]],"sub|Godsworn (2014)|Sainted Mantle":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[3,"Bonus Proficiencies",{"skills":["Medicine","Religion"],"notes":[["Note","Bonus Proficiencies: if you already have Medicine or Religion, double your Proficiency Bonus for checks with it"]]}],[3,"Anointed Mark",{"notes":[["Note","Anointed Mark: Warden's Mark on an ally within 30 ft gives it Bless while marked"]]}],[13,"Mettle",{"notes":[["Note","Mettle: a successful Constitution save against half-damage effects means no damage"]]}]],"spab":"WIS"},{"alt":[],"cls":"Warden (2014)","name":"Grey Watchman (2014)","src":"tvss14","arr":[[3,"Battle Tactics","You learn maneuvers powered by Battle Dice. You have two d8 Battle Dice. A die is expended when used. You regain all of them when you finish a Short or Long Rest or roll Initiative. The count and size grow: 3d8 at level 7, 3d10 at level 13, 4d10 at level 19. Once per turn you can expend a die for one maneuver. Saving throw DC for maneuvers: 8 + your Proficiency Bonus + your Strength or Dexterity modifier. **Bull Rush.** After a melee weapon attack made right after moving 10 feet in a straight line, spend a Bonus Action and a die to shove the target. Add the die to the Strength (Athletics) check. On a success you push it 10 feet. **Bulwark.** When you hit with a melee attack, spend a Bonus Action and a die. The next time that creature damages you before your next turn, subtract the die roll from the damage. **Cleave.** When you reduce a hostile creature to 0 HP or score a critical hit with a melee weapon attack on your turn, spend a die to move up to 15 feet and make another melee weapon attack, adding the die to the damage. **Heelcutter.** On an Opportunity Attack, spend a die and add it to the attack roll. The target makes a Strength saving throw or its Speed is 0 until the end of its turn. **Reckless Assault.** When you attack, spend a die to have Advantage on the roll. Attacks against you have Advantage until the start of your next turn. **Staggering Strike.** As a Bonus Action when you make a weapon attack, spend a die to try to stun a Humanoid. On a hit it makes a Constitution saving throw or is Incapacitated until the start of your next turn."],[3,"Hold the Line","When you use Warden's Grasp, each creature you choose in the area other than you gains +1 to AC and saving throws until the start of your next turn while it stays in the area."],[6,"Fortification Expert","You have Advantage on ability checks to build defensive fortifications, search walls and defenses for weak points or entries, or climb built walls. You can also treat cover as full cover."],[13,"Mettle","When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Unbreakable Sentinel","Action: become a paragon of battle for 1 minute. You have +2 AC. Whenever you hit a creature you have marked, you regain one expended Battle Die. You can take one extra Reaction each round, but only one per turn. Long Rest to use it again."]],"full":{"Grey Watchman (2014)|Battle Tactics":"You learn maneuvers powered by Battle Dice. You have two d8 Battle Dice. A die is expended when used. You regain all of them when you finish a Short or Long Rest or roll Initiative. The count and size grow: 3d8 at level 7, 3d10 at level 13, 4d10 at level 19. Once per turn you can expend a die for one maneuver. Saving throw DC for maneuvers: 8 + your Proficiency Bonus + your Strength or Dexterity modifier. **Bull Rush.** After a melee weapon attack made right after moving 10 feet in a straight line, spend a Bonus Action and a die to shove the target. Add the die to the Strength (Athletics) check. On a success you push it 10 feet. **Bulwark.** When you hit with a melee attack, spend a Bonus Action and a die. The next time that creature damages you before your next turn, subtract the die roll from the damage. **Cleave.** When you reduce a hostile creature to 0 HP or score a critical hit with a melee weapon attack on your turn, spend a die to move up to 15 feet and make another melee weapon attack, adding the die to the damage. **Heelcutter.** On an Opportunity Attack, spend a die and add it to the attack roll. The target makes a Strength saving throw or its Speed is 0 until the end of its turn. **Reckless Assault.** When you attack, spend a die to have Advantage on the roll. Attacks against you have Advantage until the start of your next turn. **Staggering Strike.** As a Bonus Action when you make a weapon attack, spend a die to try to stun a Humanoid. On a hit it makes a Constitution saving throw or is Incapacitated until the start of your next turn.","Grey Watchman (2014)|Hold the Line":"When you use Warden's Grasp, each creature you choose in the area other than you gains +1 to AC and saving throws until the start of your next turn while it stays in the area.","Grey Watchman (2014)|Fortification Expert":"You have Advantage on ability checks to build defensive fortifications, search walls and defenses for weak points or entries, or climb built walls. You can also treat cover as full cover.","Grey Watchman (2014)|Mettle":"When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure.","Grey Watchman (2014)|Unbreakable Sentinel":"Action: become a paragon of battle for 1 minute. You have +2 AC. Whenever you hit a creature you have marked, you regain one expended Battle Die. You can take one extra Reaction each round, but only one per turn. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Grey Watchman (2014)","feature":"Battle Tactics","n":"Battle Dice","lvl":3,"max":[0,0,2,2,2,2,3,3,3,3,3,3,3,3,3,3,3,3,4,4],"reset":"short","tag":"d8, d10 from 13"},{"src":"sub","owner":"Grey Watchman (2014)","feature":"Unbreakable Sentinel","n":"Unbreakable Sentinel","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Grey Watchman (2014)|Unbreakable Sentinel":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Hold the Line",{"notes":[["Note","Hold the Line: allies in Warden's Grasp area gain +1 AC and saving throws until your next turn"]]}],[6,"Fortification Expert",{"notes":[["Note","Fortification Expert: Advantage on checks to build or inspect fortifications and climb built walls. Cover counts as full cover"]]}],[13,"Mettle",{"notes":[["Note","Mettle: a successful Constitution save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Hellkeeper","src":"tvss14","arr":[[3,"Hellish Grasp","When you use Warden's Grasp, each creature it affects takes 1d6 Fire damage. At level 14 this becomes 2d6."],[3,"Tormenter","You gain proficiency in Intimidation, and your Proficiency Bonus is doubled for Charisma (Intimidation) checks to intimidate a Restrained creature."],[6,"Fell Resilience","While your HP is below half your maximum, you have Advantage on Strength and Constitution saving throws."],[6,"Spiteful Mark","When you mark a creature with Warden's Mark, it takes 1d6 Fire damage. At level 11 this becomes 2d6."],[13,"Evasion","When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Hellbent","Action: take the shape of a true devil for 1 minute. Your melee weapon attacks deal an extra 2d8 Fire damage on a hit. Fire damage you deal ignores Resistance and Immunity. Once during the duration, if you fail a saving throw you can succeed instead. Long Rest to use it again."]],"full":{"Hellkeeper|Hellish Grasp":"When you use Warden's Grasp, each creature it affects takes 1d6 Fire damage. At level 14 this becomes 2d6.","Hellkeeper|Tormenter":"You gain proficiency in Intimidation, and your Proficiency Bonus is doubled for Charisma (Intimidation) checks to intimidate a Restrained creature.","Hellkeeper|Fell Resilience":"While your HP is below half your maximum, you have Advantage on Strength and Constitution saving throws.","Hellkeeper|Spiteful Mark":"When you mark a creature with Warden's Mark, it takes 1d6 Fire damage. At level 11 this becomes 2d6.","Hellkeeper|Evasion":"When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure.","Hellkeeper|Hellbent":"Action: take the shape of a true devil for 1 minute. Your melee weapon attacks deal an extra 2d8 Fire damage on a hit. Fire damage you deal ignores Resistance and Immunity. Once during the duration, if you fail a saving throw you can succeed instead. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Hellkeeper","feature":"Hellbent","n":"Hellbent","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Hellkeeper|Hellbent":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Tormenter",{"skills":["Intimidation"],"notes":[["Note","Tormenter: double Proficiency Bonus on Intimidation checks against a Restrained creature"]]}],[3,"Hellish Grasp",{"notes":[["Note","Hellish Grasp: creatures in Warden's Grasp take 1d6 Fire (2d6 at level 14)"]]}],[6,"Fell Resilience",{"notes":[["Note","Fell Resilience: below half HP, Advantage on Strength and Constitution saves"]]}],[6,"Spiteful Mark",{"notes":[["Note","Spiteful Mark: a creature you mark takes 1d6 Fire (2d6 at level 11)"]]}],[13,"Evasion",{"notes":[["Note","Evasion: a successful Dexterity save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Iceheart Bastion","src":"tvss14","arr":[[3,"Icy Grasp","When you use Warden's Grasp, ice anchors you to the ground and you gain Temporary Hit Points equal to your Constitution modifier until the start of your next turn."],[3,"Snowshoes","You ignore Difficult Terrain caused by snow and ice, and it does not slow your travel."],[6,"North Wind","Breathe out an icy gale in a line 100 feet long and 5 feet wide. Each creature in it makes a Dexterity saving throw. On a failure it takes 4d6 Cold damage and its Speed is halved until the end of its next turn. On a success it takes half damage and its Speed is unchanged. Short or Long Rest to use it again."],[13,"Mettle","When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Form of the Old Hoarfrost","Action: turn into a creature of deep cold for 1 minute. A 15-foot-radius freezing vortex surrounds you and puts out nonmagical flames. The area is Difficult Terrain. A creature that first enters it on a turn or starts its turn there takes 8d6 Cold damage. You can exempt creatures from the effects. Long Rest to use it again."]],"full":{"Iceheart Bastion|Icy Grasp":"When you use Warden's Grasp, ice anchors you to the ground and you gain Temporary Hit Points equal to your Constitution modifier until the start of your next turn.","Iceheart Bastion|Snowshoes":"You ignore Difficult Terrain caused by snow and ice, and it does not slow your travel.","Iceheart Bastion|North Wind":"Breathe out an icy gale in a line 100 feet long and 5 feet wide. Each creature in it makes a Dexterity saving throw. On a failure it takes 4d6 Cold damage and its Speed is halved until the end of its next turn. On a success it takes half damage and its Speed is unchanged. Short or Long Rest to use it again.","Iceheart Bastion|Mettle":"When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure.","Iceheart Bastion|Form of the Old Hoarfrost":"Action: turn into a creature of deep cold for 1 minute. A 15-foot-radius freezing vortex surrounds you and puts out nonmagical flames. The area is Difficult Terrain. A creature that first enters it on a turn or starts its turn there takes 8d6 Cold damage. You can exempt creatures from the effects. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Iceheart Bastion","feature":"North Wind","n":"North Wind","lvl":6,"max":1,"reset":"short","tag":"100 ft line, 4d6 Cold"},{"src":"sub","owner":"Iceheart Bastion","feature":"Form of the Old Hoarfrost","n":"Form of the Old Hoarfrost","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Iceheart Bastion|North Wind":[["action",""]],"sub|Iceheart Bastion|Form of the Old Hoarfrost":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Icy Grasp",{"notes":[["Note","Icy Grasp: Warden's Grasp gives you Temporary HP equal to your Constitution modifier until your next turn"]]}],[3,"Snowshoes",{"notes":[["Note","Snowshoes: ignore Difficult Terrain from snow and ice"]]}],[13,"Mettle",{"notes":[["Note","Mettle: a successful Constitution save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Jolly Roger Banner","src":"tvss14","arr":[[3,"Maneuver: Double Thrust","When you attack with a finesse weapon as part of the Attack action on your turn, spend a battle die as a Bonus Action to make one more attack with it. That attack adds the die to the damage instead of your ability modifier."],[7,"Tricky Footwork","When you hit a creature of your size or smaller with a melee attack on your turn, you can swap places with the target. This does not provoke Opportunity Attacks."],[13,"Unfair Play","You and your cohort can use a Bonus Action to take the Hide or Use an Object action, or to try to shove a creature. You have Advantage on Strength (Athletics) checks to push another creature out of a boat or other vessel on water."],[17,"All Hands on Deck","As an action on your turn you direct each friendly creature within 60 feet that can see or hear you to take an action of its choice, other than Attack, Cast a Spell, Dodge or Use a Magic Item. Each can use its Reaction at once to do so."]],"full":{"Jolly Roger Banner|Maneuver: Double Thrust":"When you attack with a finesse weapon as part of the Attack action on your turn, spend a battle die as a Bonus Action to make one more attack with it. That attack adds the die to the damage instead of your ability modifier.","Jolly Roger Banner|Tricky Footwork":"When you hit a creature of your size or smaller with a melee attack on your turn, you can swap places with the target. This does not provoke Opportunity Attacks.","Jolly Roger Banner|Unfair Play":"You and your cohort can use a Bonus Action to take the Hide or Use an Object action, or to try to shove a creature. You have Advantage on Strength (Athletics) checks to push another creature out of a boat or other vessel on water.","Jolly Roger Banner|All Hands on Deck":"As an action on your turn you direct each friendly creature within 60 feet that can see or hear you to take an action of its choice, other than Attack, Cast a Spell, Dodge or Use a Magic Item. Each can use its Reaction at once to do so."},"auto":[],"lu":[],"acts":{"sub|Jolly Roger Banner|All Hands on Deck":[["action",""]]},"cantrips":[],"pick":[],"fx":[],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Lion Banner (2014)","src":"tvss14","arr":[[3,"Maneuver: Lion's Challenge","When you hit a creature with a weapon attack on your turn, spend a battle die as a Bonus Action to challenge it to a duel. Until the end of your next turn it has Disadvantage on attack rolls that are not against you."],[7,"Saddle Sure","You have Advantage on saves to avoid falling off your mount, and you land on your feet if you fall unless Incapacitated. Mounting or dismounting costs you only 5 feet of movement. You can force an attack aimed at your mount to target you instead."],[13,"Reposition","When you roll Initiative, you and up to three friendly creatures you can see can each move up to 20 feet. A creature with 0 Speed cannot benefit."],[17,"Lion's Gambit","When a creature within 5 feet damages you, you can use your Reaction to make a melee weapon attack against it. On a hit you add half your level to the damage. You can do this three times, and a Short or Long Rest restores all uses."]],"full":{"Lion Banner (2014)|Maneuver: Lion's Challenge":"When you hit a creature with a weapon attack on your turn, spend a battle die as a Bonus Action to challenge it to a duel. Until the end of your next turn it has Disadvantage on attack rolls that are not against you.","Lion Banner (2014)|Saddle Sure":"You have Advantage on saves to avoid falling off your mount, and you land on your feet if you fall unless Incapacitated. Mounting or dismounting costs you only 5 feet of movement. You can force an attack aimed at your mount to target you instead.","Lion Banner (2014)|Reposition":"When you roll Initiative, you and up to three friendly creatures you can see can each move up to 20 feet. A creature with 0 Speed cannot benefit.","Lion Banner (2014)|Lion's Gambit":"When a creature within 5 feet damages you, you can use your Reaction to make a melee weapon attack against it. On a hit you add half your level to the damage. You can do this three times, and a Short or Long Rest restores all uses."},"auto":[],"lu":[{"src":"sub","owner":"Lion Banner (2014)","feature":"Lion's Gambit","n":"Lion's Gambit","lvl":17,"max":3,"reset":"short","tag":"Reaction"}],"acts":{"sub|Lion Banner (2014)|Lion's Gambit":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Loreseeker","src":"tvss14","arr":[[3,"Bookmark","A creature you have marked subtracts 1d4 from saving throws against your spells and effects."],[3,"Spellcasting","You cast Wizard spells using Intelligence. **Cantrips.** Learn two Wizard cantrips, and a third at level 10. **Spell slots.** The Loreseeker Spellcasting table gives your slots. They return on a Long Rest. **Spells known.** You know three level 1 Wizard spells, two of which must be Abjuration or Evocation. The table shows when you learn more. Each must be Abjuration or Evocation and of a level you have slots for, except those learned at levels 8, 14 and 20, which can be from any school. When you gain a Warden level you can swap one spell for another that follows the same rule. **Spellcasting ability.** Intelligence. Spell save DC is 8 + your Proficiency Bonus + your Intelligence modifier. Spell attack bonus is your Proficiency Bonus + your Intelligence modifier. You can use an arcane focus as a spellcasting focus."],[6,"Ensnaring Mark","When you put Warden's Mark on a creature, you can teleport it to an unoccupied space within 5 feet of you. Short or Long Rest to use it again."],[13,"Spell Resistance","You have Advantage on saving throws against spells."],[20,"Librarian of the Eternal","Action: become a living store of ancient lore for 1 minute. When you cast a spell you gain 15 Temporary Hit Points. A cantrip with a casting time of 1 action can be cast as a Bonus Action. A creature you have marked has Disadvantage on saving throws against your spells. Long Rest to use it again."]],"full":{"Loreseeker|Bookmark":"A creature you have marked subtracts 1d4 from saving throws against your spells and effects.","Loreseeker|Spellcasting":"You cast Wizard spells using Intelligence. **Cantrips.** Learn two Wizard cantrips, and a third at level 10. **Spell slots.** The Loreseeker Spellcasting table gives your slots. They return on a Long Rest. **Spells known.** You know three level 1 Wizard spells, two of which must be Abjuration or Evocation. The table shows when you learn more. Each must be Abjuration or Evocation and of a level you have slots for, except those learned at levels 8, 14 and 20, which can be from any school. When you gain a Warden level you can swap one spell for another that follows the same rule. **Spellcasting ability.** Intelligence. Spell save DC is 8 + your Proficiency Bonus + your Intelligence modifier. Spell attack bonus is your Proficiency Bonus + your Intelligence modifier. You can use an arcane focus as a spellcasting focus.","Loreseeker|Ensnaring Mark":"When you put Warden's Mark on a creature, you can teleport it to an unoccupied space within 5 feet of you. Short or Long Rest to use it again.","Loreseeker|Spell Resistance":"You have Advantage on saving throws against spells.","Loreseeker|Librarian of the Eternal":"Action: become a living store of ancient lore for 1 minute. When you cast a spell you gain 15 Temporary Hit Points. A cantrip with a casting time of 1 action can be cast as a Bonus Action. A creature you have marked has Disadvantage on saving throws against your spells. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Loreseeker","feature":"Ensnaring Mark","n":"Ensnaring Mark","lvl":6,"max":1,"reset":"short","tag":"Teleport the marked creature"},{"src":"sub","owner":"Loreseeker","feature":"Librarian of the Eternal","n":"Librarian of the Eternal","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Loreseeker|Librarian of the Eternal":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Bookmark",{"notes":[["Note","Bookmark: a marked creature subtracts 1d4 from saves against your spells and effects"]]}],[6,"Ensnaring Mark",{"notes":[["Note","Ensnaring Mark: teleport the creature you mark to within 5 feet of you (once per rest)"]]}]],"spab":"INT","third":{"list":"Wizard","ab":"INT","cant":2},"gx":[{"l":13,"n":"Spell Resistance","advOn":["saving throws against spells"]}]},{"alt":[],"cls":"Alchemist (2014)","name":"Mad Bomber (2014)","src":"tvss14","arr":[[3,"Blasting Specialty","Your Bombs deal double damage to objects and structures."],[3,"Formula: Shrapnel Bomb","Bomb formula: Shrapnel Bomb. It deals Piercing damage instead of Fire, with d8 dice, and explodes in a 10-foot radius."],[6,"Timed Demolition","When you prime and throw a Bomb you can set a delay of up to one minute (any number of 6-second rounds). It detonates at the end of your turn when the delay runs out."],[10,"Blast Shield","You have Resistance to your choice of Acid, Cold, Fire or Lightning damage. You can change the choice after a Long Rest."],[18,"Formula: Black Powder Bomb","Bomb formula: Black Powder Bomb. Replace the explosive core with a charge of black powder. The Bomb's damage dice are d12s."]],"full":{"Mad Bomber (2014)|Blasting Specialty":"Your Bombs deal double damage to objects and structures.","Mad Bomber (2014)|Formula: Shrapnel Bomb":"Bomb formula: Shrapnel Bomb. It deals Piercing damage instead of Fire, with d8 dice, and explodes in a 10-foot radius.","Mad Bomber (2014)|Timed Demolition":"When you prime and throw a Bomb you can set a delay of up to one minute (any number of 6-second rounds). It detonates at the end of your turn when the delay runs out.","Mad Bomber (2014)|Blast Shield":"You have Resistance to your choice of Acid, Cold, Fire or Lightning damage. You can change the choice after a Long Rest.","Mad Bomber (2014)|Formula: Black Powder Bomb":"Bomb formula: Black Powder Bomb. Replace the explosive core with a charge of black powder. The Bomb's damage dice are d12s."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[10,"Blast Shield",{"notes":[["Note","Blast Shield: Resistance to Acid, Cold, Fire or Lightning (your choice, change after a Long Rest)"]]}]],"spab":""},{"alt":[],"cls":"Alchemist (2014)","name":"Mutagenist (2014)","src":"tvss14","arr":[[3,"Bonus Proficiencies","You gain proficiency in Acrobatics or Athletics (your choice) and with shields."],[3,"Mutagen","As a Bonus Action you inject a mutagen and pick one benefit for 1 minute, or until you inject a different one. **Strength.** Strength +3 (max 20). You also grow a natural weapon and your Unarmed Strikes deal 1d4 plus Strength, Bludgeoning, Piercing or Slashing to fit it. **Dexterity.** Dexterity +3 (max 20) and Speed +5 feet. **Constitution.** Constitution +3 (max 20). Your current and maximum HP rise with the new score, and both drop by the same amount when the effect ends."],[6,"Shared Mutagen","As an action you can spend one reagent die to inject a willing creature within 5 feet with a mutagen of your choice. A creature can be under one mutagen at a time. After you inject another creature you cannot do it again until the first mutagen ends."],[10,"Advanced Mutation","When you inject a mutagen, you can pick one extra mutation. **Hyperelastic.** Your melee weapon attacks gain Reach, and you have Advantage on checks to escape a grapple or slip bonds. **Mucilaginous.** You climb vertical surfaces and ceilings with your hands free, you have a Climb Speed equal to your Speed, and creatures have Disadvantage on checks to escape your grapple. **Polybrachia.** You grow two more arms that can hold weapons and shields (two two-handed weapons or four one-handed), make somatic components and do other actions, but give no extra actions."],[18,"Mutated Blood","Choose Strength, Dexterity or Constitution. That score rises by 2 and its maximum becomes 22. You cannot change the choice."]],"full":{"Mutagenist (2014)|Bonus Proficiencies":"You gain proficiency in Acrobatics or Athletics (your choice) and with shields.","Mutagenist (2014)|Mutagen":"As a Bonus Action you inject a mutagen and pick one benefit for 1 minute, or until you inject a different one. **Strength.** Strength +3 (max 20). You also grow a natural weapon and your Unarmed Strikes deal 1d4 plus Strength, Bludgeoning, Piercing or Slashing to fit it. **Dexterity.** Dexterity +3 (max 20) and Speed +5 feet. **Constitution.** Constitution +3 (max 20). Your current and maximum HP rise with the new score, and both drop by the same amount when the effect ends.","Mutagenist (2014)|Shared Mutagen":"As an action you can spend one reagent die to inject a willing creature within 5 feet with a mutagen of your choice. A creature can be under one mutagen at a time. After you inject another creature you cannot do it again until the first mutagen ends.","Mutagenist (2014)|Advanced Mutation":"When you inject a mutagen, you can pick one extra mutation. **Hyperelastic.** Your melee weapon attacks gain Reach, and you have Advantage on checks to escape a grapple or slip bonds. **Mucilaginous.** You climb vertical surfaces and ceilings with your hands free, you have a Climb Speed equal to your Speed, and creatures have Disadvantage on checks to escape your grapple. **Polybrachia.** You grow two more arms that can hold weapons and shields (two two-handed weapons or four one-handed), make somatic components and do other actions, but give no extra actions.","Mutagenist (2014)|Mutated Blood":"Choose Strength, Dexterity or Constitution. That score rises by 2 and its maximum becomes 22. You cannot change the choice."},"auto":[],"lu":[],"acts":{"sub|Mutagenist (2014)|Mutagen":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[2,"Bonus Proficiencies",{"notes":[["Note","Bonus Proficiencies: Shield training. Proficiency in Acrobatics or Athletics (your choice)"]]}],[2,"Mutagen",{"notes":[["Note","Mutagen: Bonus Action, 1 minute. Strength +3, or Dexterity +3 and Speed +5 ft, or Constitution +3 (max 20)"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Nightgaunt (2014)","src":"tvss14","arr":[[3,"Darkvision","You see in dim light within 60 feet as if it were bright, and in darkness as if it were dim, but only in shades of gray. If you already have Darkvision, its range grows by 30 feet. From level 13 you can see through magical darkness too."],[3,"Marked for Death","Your mark leaves a shadow of undeath on the target. If you deal damage to a creature you have marked with a melee weapon attack and its remaining HP is lower than the damage you dealt, it drops to 0 HP."],[6,"Undead Empathy","When an Undead tries to attack you, it makes a Wisdom saving throw (DC 8 + your Proficiency Bonus + your Constitution modifier). On a failure its attack misses, and if its Intelligence is 4 or lower it becomes friendly to you and your allies."],[13,"Evasion","When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Gravelord","Action: take in the power of true undead for 1 minute. You are immune to Poison damage and the Poisoned condition. You can use Undying up to three times, even if you have used it today. Once per turn when you deal damage with a melee weapon attack, you can deal an extra 4d6 Necrotic damage and gain Temporary HP equal to it, lasting until the start of your next turn. Long Rest to use it again."]],"full":{"Nightgaunt (2014)|Darkvision":"You see in dim light within 60 feet as if it were bright, and in darkness as if it were dim, but only in shades of gray. If you already have Darkvision, its range grows by 30 feet. From level 13 you can see through magical darkness too.","Nightgaunt (2014)|Marked for Death":"Your mark leaves a shadow of undeath on the target. If you deal damage to a creature you have marked with a melee weapon attack and its remaining HP is lower than the damage you dealt, it drops to 0 HP.","Nightgaunt (2014)|Undead Empathy":"When an Undead tries to attack you, it makes a Wisdom saving throw (DC 8 + your Proficiency Bonus + your Constitution modifier). On a failure its attack misses, and if its Intelligence is 4 or lower it becomes friendly to you and your allies.","Nightgaunt (2014)|Evasion":"When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure.","Nightgaunt (2014)|Gravelord":"Action: take in the power of true undead for 1 minute. You are immune to Poison damage and the Poisoned condition. You can use Undying up to three times, even if you have used it today. Once per turn when you deal damage with a melee weapon attack, you can deal an extra 4d6 Necrotic damage and gain Temporary HP equal to it, lasting until the start of your next turn. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Nightgaunt (2014)","feature":"Gravelord","n":"Gravelord","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Nightgaunt (2014)|Gravelord":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Darkvision",{"notes":[["Note","Darkvision: if you already have Darkvision, add 30 feet to its range. From level 13 it sees through magical darkness"]]}],[3,"Marked for Death",{"notes":[["Note","Marked for Death: a melee hit on your marked creature drops it to 0 HP if its remaining HP is lower than the damage dealt"]]}],[6,"Undead Empathy",{"notes":[["Note","Undead Empathy: an Undead attacking you makes a Wisdom save (DC 8 + PB + CON) or misses, and may turn friendly if Intelligence 4 or lower"]]}],[13,"Evasion",{"notes":[["Note","Evasion: a successful Dexterity save against half-damage effects means no damage"]]}]],"spab":"","gx":[{"l":3,"n":"Darkvision","darkTo":60}]},{"alt":[],"cls":"Alchemist (2014)","name":"Ooze Rancher (2014)","src":"tvss14","arr":[[3,"Formula: Slime Bomb","Bomb formula: Slime Bomb. The Bomb deals no damage. Each creature in the blast is coated in green slime and cannot Dash or Disengage. A gallon of water or an action to scrape it off removes it."],[3,"Ooze Empathy","When an Ooze tries to attack you, it makes a Wisdom save against your Bomb save DC. On a failure its attack misses. On a success it is immune to this for 24 hours."],[6,"Bottled Oozes","When you brew potions you can spend 2 reagent dice to make an Ooze Bottle."],[10,"Liquid Anatomy","You can move through a space as narrow as 1 inch without squeezing (your gear does not compress), and you take no extra damage from critical hits."],[18,"Ooze Jug","You have one ooze jug, which works like an Ooze Bottle but holds a larger ooze. You can have one at a time and fill it when you brew potions with: Ochre Jelly (4 reagent dice), Gelatinous Cube (8) or Black Pudding (10)."]],"full":{"Ooze Rancher (2014)|Formula: Slime Bomb":"Bomb formula: Slime Bomb. The Bomb deals no damage. Each creature in the blast is coated in green slime and cannot Dash or Disengage. A gallon of water or an action to scrape it off removes it.","Ooze Rancher (2014)|Ooze Empathy":"When an Ooze tries to attack you, it makes a Wisdom save against your Bomb save DC. On a failure its attack misses. On a success it is immune to this for 24 hours.","Ooze Rancher (2014)|Bottled Oozes":"When you brew potions you can spend 2 reagent dice to make an Ooze Bottle.","Ooze Rancher (2014)|Liquid Anatomy":"You can move through a space as narrow as 1 inch without squeezing (your gear does not compress), and you take no extra damage from critical hits.","Ooze Rancher (2014)|Ooze Jug":"You have one ooze jug, which works like an Ooze Bottle but holds a larger ooze. You can have one at a time and fill it when you brew potions with: Ochre Jelly (4 reagent dice), Gelatinous Cube (8) or Black Pudding (10)."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[2,"Ooze Empathy",{"notes":[["Note","Ooze Empathy: an Ooze attacking you makes a Wisdom save (Bomb save DC) or misses"]]}],[10,"Liquid Anatomy",{"notes":[["Note","Liquid Anatomy: squeeze through 1-inch gaps. Critical hits deal no extra damage to you"]]}]],"spab":""},{"alt":[],"cls":"Alchemist (2014)","name":"Pigmentist (2014)","src":"tvss14","arr":[[3,"Bonus Proficiencies","You gain proficiency with painter's supplies. Each time you make Bombs after a rest you can also make a gallon of paint."],[3,"Formula: Paint Bomb","Bomb formula: Paint Bomb. Its dice are d6s. When you prime it, pick a color. Each creature in the blast is coated until the paint dries after 1 minute, a gallon of water washes it off, or a new coat goes on. **Blue.** Once per turn when the target takes Cold damage, it takes extra Cold equal to the Bomb damage roll. **Green.** The target treats the blast area as Difficult Terrain. **Indigo.** Once per turn when the target fails a Strength, Dexterity or Constitution save, it takes Force damage equal to the Bomb damage roll. **Orange.** When the target ends its turn in the blast area, it takes Acid damage equal to the Bomb damage roll. **Red.** Once per turn when the target takes Fire damage, it takes extra Fire equal to the Bomb damage roll. **Violet.** Once per turn when the target fails an Intelligence, Wisdom or Charisma save, it takes Force damage equal to the Bomb damage roll. **Yellow.** When the target ends its turn in the blast area, it takes Lightning damage equal to the Bomb damage roll."],[6,"Illusory Paintings","You can lace your paint with a small amount of illusion. When you paint an object, you can give it the effect of a Silent Image contained within the painting's edges, such as a lion that walks along a wall or a lantern that gives light. The illusion lasts 1 hour after drying if painted in under 10 minutes, 24 hours if painted over an hour, and until dispelled if painted over 24 hours or more."],[10,"Improved Paint Bomb","You can fill Paint Bombs with white and black paint. A creature coated in white has its AC raised by 1d6 (max 20) and adds 1d6 to its saves. A creature coated in black has its AC lowered by 1d6 (min 10) and subtracts 1d6 from its saves."],[18,"Rainbow Blast","When you prime and throw a Bomb whose formula has a blast radius, you can also turn it into a Paint Bomb of any color except white or black. It first applies its original formula, including damage, then coats the creatures in the blast."]],"full":{"Pigmentist (2014)|Bonus Proficiencies":"You gain proficiency with painter's supplies. Each time you make Bombs after a rest you can also make a gallon of paint.","Pigmentist (2014)|Formula: Paint Bomb":"Bomb formula: Paint Bomb. Its dice are d6s. When you prime it, pick a color. Each creature in the blast is coated until the paint dries after 1 minute, a gallon of water washes it off, or a new coat goes on. **Blue.** Once per turn when the target takes Cold damage, it takes extra Cold equal to the Bomb damage roll. **Green.** The target treats the blast area as Difficult Terrain. **Indigo.** Once per turn when the target fails a Strength, Dexterity or Constitution save, it takes Force damage equal to the Bomb damage roll. **Orange.** When the target ends its turn in the blast area, it takes Acid damage equal to the Bomb damage roll. **Red.** Once per turn when the target takes Fire damage, it takes extra Fire equal to the Bomb damage roll. **Violet.** Once per turn when the target fails an Intelligence, Wisdom or Charisma save, it takes Force damage equal to the Bomb damage roll. **Yellow.** When the target ends its turn in the blast area, it takes Lightning damage equal to the Bomb damage roll.","Pigmentist (2014)|Illusory Paintings":"You can lace your paint with a small amount of illusion. When you paint an object, you can give it the effect of a Silent Image contained within the painting's edges, such as a lion that walks along a wall or a lantern that gives light. The illusion lasts 1 hour after drying if painted in under 10 minutes, 24 hours if painted over an hour, and until dispelled if painted over 24 hours or more.","Pigmentist (2014)|Improved Paint Bomb":"You can fill Paint Bombs with white and black paint. A creature coated in white has its AC raised by 1d6 (max 20) and adds 1d6 to its saves. A creature coated in black has its AC lowered by 1d6 (min 10) and subtracts 1d6 from its saves.","Pigmentist (2014)|Rainbow Blast":"When you prime and throw a Bomb whose formula has a blast radius, you can also turn it into a Paint Bomb of any color except white or black. It first applies its original formula, including damage, then coats the creatures in the blast."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[2,"Bonus Proficiencies",{"notes":[["Note","Bonus Proficiencies: proficiency with painter's supplies"]]}]],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Ram Banner","src":"tvss14","arr":[[3,"Maneuver: Bull Rush","When you move at least 10 feet in a straight line and then make a melee weapon attack against a creature, spend a Bonus Action and a battle die to shove it after the attack. Add the die to the Strength (Athletics) check. On a success you can knock the target Prone or push it up to 10 feet away."],[7,"Surefooted","Nonmagical Difficult Terrain costs you no extra movement."],[13,"Lock Horns","When you shove a creature into one of your allies, that ally can use its Reaction to attack the shoved creature."],[17,"And Stay Down","When a creature within your reach stands up from Prone, you can make an Opportunity Attack against it."]],"full":{"Ram Banner|Maneuver: Bull Rush":"When you move at least 10 feet in a straight line and then make a melee weapon attack against a creature, spend a Bonus Action and a battle die to shove it after the attack. Add the die to the Strength (Athletics) check. On a success you can knock the target Prone or push it up to 10 feet away.","Ram Banner|Surefooted":"Nonmagical Difficult Terrain costs you no extra movement.","Ram Banner|Lock Horns":"When you shove a creature into one of your allies, that ally can use its Reaction to attack the shoved creature.","Ram Banner|And Stay Down":"When a creature within your reach stands up from Prone, you can make an Opportunity Attack against it."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[7,"Surefooted",{"notes":[["Note","Surefooted: nonmagical Difficult Terrain costs no extra movement"]]}]],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Raven Banner","src":"tvss14","arr":[[3,"Maneuver: Effortless Dodge","As a Bonus Action, spend a battle die to take the Dodge action. You cannot use this while wearing medium or heavy armor."],[3,"Maneuver: Flanking Strike","When you hit a creature with a weapon attack while an ally is within 5 feet of it, spend a battle die to strike a vital spot. Add the die and half your level (rounded down) to the damage. The attack must use a finesse or light weapon."],[7,"Covert","When you are hidden and a creature spots you with a Wisdom (Perception) check, you can retry your Dexterity (Stealth) check. On a success you slip away unnoticed. Short or Long Rest to use it again."],[13,"Strike First, Strike Last","As a Reaction when a hostile creature you can see attacks, you move up to your Speed toward it without provoking Opportunity Attacks and make one attack against it. Resolve your attack before the creature attacks. Long Rest to use it again."],[17,"Guerilla Warfare","You have Advantage on attack rolls against creatures that have not taken a turn in the combat yet. The first time you hit a creature during the first round of combat, you add two battle dice to the damage without spending them."]],"full":{"Raven Banner|Maneuver: Effortless Dodge":"As a Bonus Action, spend a battle die to take the Dodge action. You cannot use this while wearing medium or heavy armor.","Raven Banner|Maneuver: Flanking Strike":"When you hit a creature with a weapon attack while an ally is within 5 feet of it, spend a battle die to strike a vital spot. Add the die and half your level (rounded down) to the damage. The attack must use a finesse or light weapon.","Raven Banner|Covert":"When you are hidden and a creature spots you with a Wisdom (Perception) check, you can retry your Dexterity (Stealth) check. On a success you slip away unnoticed. Short or Long Rest to use it again.","Raven Banner|Strike First, Strike Last":"As a Reaction when a hostile creature you can see attacks, you move up to your Speed toward it without provoking Opportunity Attacks and make one attack against it. Resolve your attack before the creature attacks. Long Rest to use it again.","Raven Banner|Guerilla Warfare":"You have Advantage on attack rolls against creatures that have not taken a turn in the combat yet. The first time you hit a creature during the first round of combat, you add two battle dice to the damage without spending them."},"auto":[],"lu":[{"src":"sub","owner":"Raven Banner","feature":"Covert","n":"Covert","lvl":7,"max":1,"reset":"short","tag":"Retry hide"},{"src":"sub","owner":"Raven Banner","feature":"Strike First, Strike Last","n":"Strike First, Strike Last","lvl":13,"max":1,"reset":"long","tag":"Reaction"}],"acts":{"sub|Raven Banner|Strike First, Strike Last":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[],"spab":""},{"alt":[],"cls":"Alchemist (2014)","name":"Resonator (2014)","src":"tvss14","arr":[[3,"Formula: Conical Bomb","Bomb formula: Conical Bomb. Attach a waveguide so the blast is a 15-foot cone from the point of impact, facing a direction you choose. It deals Thunder damage instead of Fire, with d6 dice, and uses a Constitution save."],[3,"Playback Device","You build a clockwork recorder. It records anything you heard in the last minute and stores up to 8 hours of audio, played back identically, but it cannot be loud enough to Deafen or damage. You can play it up to three times as loud, as a megaphone. If lost, you can rebuild it for 100 GP during a Long Rest."],[6,"Resonant Frequency","As an action you pick one solid material (wood, glass, metal, stone) and play its resonant tone. Unworn, uncarried objects of that material within 15 feet take 1d8 plus your Intelligence modifier Force damage at the start of each of your turns. Constructs or Elementals made mostly of one material, and parts of objects such as a metal lock, can be hurt too. You can stop on your turn with no action."],[10,"Improved Flashbang","Your flashbangs affect creatures within 10 feet. You can choose creatures in the area to be unaffected. They also affect Huge creatures."],[18,"Formula: Reverb Bomb","Bomb formula: Reverb Bomb. It deals Thunder damage instead of Fire, with d8 dice, and uses a Constitution save. After it hits a target, it explodes again in the same radius at the start of your turn for the next two rounds, each time with weaker force: creatures in the blast save or take half the Bomb damage. On your next turn its dice are d6s, then d4s. It ends early if you use a Reverb Bomb again."]],"full":{"Resonator (2014)|Formula: Conical Bomb":"Bomb formula: Conical Bomb. Attach a waveguide so the blast is a 15-foot cone from the point of impact, facing a direction you choose. It deals Thunder damage instead of Fire, with d6 dice, and uses a Constitution save.","Resonator (2014)|Playback Device":"You build a clockwork recorder. It records anything you heard in the last minute and stores up to 8 hours of audio, played back identically, but it cannot be loud enough to Deafen or damage. You can play it up to three times as loud, as a megaphone. If lost, you can rebuild it for 100 GP during a Long Rest.","Resonator (2014)|Resonant Frequency":"As an action you pick one solid material (wood, glass, metal, stone) and play its resonant tone. Unworn, uncarried objects of that material within 15 feet take 1d8 plus your Intelligence modifier Force damage at the start of each of your turns. Constructs or Elementals made mostly of one material, and parts of objects such as a metal lock, can be hurt too. You can stop on your turn with no action.","Resonator (2014)|Improved Flashbang":"Your flashbangs affect creatures within 10 feet. You can choose creatures in the area to be unaffected. They also affect Huge creatures.","Resonator (2014)|Formula: Reverb Bomb":"Bomb formula: Reverb Bomb. It deals Thunder damage instead of Fire, with d8 dice, and uses a Constitution save. After it hits a target, it explodes again in the same radius at the start of your turn for the next two rounds, each time with weaker force: creatures in the blast save or take half the Bomb damage. On your next turn its dice are d6s, then d4s. It ends early if you use a Reverb Bomb again."},"auto":[],"lu":[],"acts":{"sub|Resonator (2014)|Resonant Frequency":[["action",""]]},"cantrips":[],"pick":[],"fx":[],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Siegeball Banner","src":"tvss14","arr":[[3,"Sports Enthusiast","You gain proficiency in Athletics (or double your Proficiency Bonus if you have it) and in improvised weapons tied to sports, such as bats, clubs and darts."],[3,"Team Player","As a Bonus Action you can give one of your unspent battle dice to a creature within 60 feet that can hear you. Once within the next minute, it can roll the die and add the result to one ability check, attack roll or saving throw, deciding after the d20 but before the GM says whether it succeeds. After you use this, you cannot use it again for 1 minute."],[7,"Superfan","You have Advantage on ability checks to play a sport or to recall facts about a sport or its teams."],[13,"Incisive Taunt","As a Bonus Action you mock a creature within 15 feet. If it can hear you and understands a language, it has Disadvantage on attack rolls against creatures other than you until the end of its next turn. You can use this a number of times equal to your Charisma modifier (minimum 1). Spend a battle die to regain a use. A Long Rest restores all uses."],[17,"Game-Winning Play","If you drop to 0 HP, you can use your Reaction to delay falling Unconscious. You then move up to twice your Speed without provoking Opportunity Attacks and take an action. Damage still causes death save failures, and three failures can still kill you. After this you fall Unconscious if you are still at 0 HP. Long Rest to use it again."]],"full":{"Siegeball Banner|Sports Enthusiast":"You gain proficiency in Athletics (or double your Proficiency Bonus if you have it) and in improvised weapons tied to sports, such as bats, clubs and darts.","Siegeball Banner|Team Player":"As a Bonus Action you can give one of your unspent battle dice to a creature within 60 feet that can hear you. Once within the next minute, it can roll the die and add the result to one ability check, attack roll or saving throw, deciding after the d20 but before the GM says whether it succeeds. After you use this, you cannot use it again for 1 minute.","Siegeball Banner|Superfan":"You have Advantage on ability checks to play a sport or to recall facts about a sport or its teams.","Siegeball Banner|Incisive Taunt":"As a Bonus Action you mock a creature within 15 feet. If it can hear you and understands a language, it has Disadvantage on attack rolls against creatures other than you until the end of its next turn. You can use this a number of times equal to your Charisma modifier (minimum 1). Spend a battle die to regain a use. A Long Rest restores all uses.","Siegeball Banner|Game-Winning Play":"If you drop to 0 HP, you can use your Reaction to delay falling Unconscious. You then move up to twice your Speed without provoking Opportunity Attacks and take an action. Damage still causes death save failures, and three failures can still kill you. After this you fall Unconscious if you are still at 0 HP. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Siegeball Banner","feature":"Incisive Taunt","n":"Incisive Taunt","lvl":13,"max":"mod:CHA","reset":"long","tag":"Bonus Action"},{"src":"sub","owner":"Siegeball Banner","feature":"Game-Winning Play","n":"Game-Winning Play","lvl":17,"max":1,"reset":"long","tag":"Reaction"}],"acts":{"sub|Siegeball Banner|Team Player":[["bonus",""]],"sub|Siegeball Banner|Incisive Taunt":[["bonus",""]],"sub|Siegeball Banner|Game-Winning Play":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Sports Enthusiast",{"skills":["Athletics"],"notes":[["Note","Sports Enthusiast: if already proficient in Athletics, double your Proficiency Bonus for it. Proficient with sports improvised weapons"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Soulblood Shaman","src":"tvss14","arr":[[3,"Soulblood","As a Reaction when a creature within 5 feet damages you, you can mark that creature."],[3,"Spellcasting","You cast Druid spells using Wisdom. **Cantrips.** Learn two Druid cantrips, and a third at level 10. **Spell slots.** The Soulblood Shaman Spellcasting table gives your slots. They return on a Long Rest. **Spells known.** You know three level 1 Druid spells, two of which must be Evocation or Transmutation. The table shows when you learn more. Each must be Evocation or Transmutation and of a level you have slots for, except those learned at levels 8, 14 and 20, which can be from any school. When you gain a Warden level you can swap one spell for another that follows the same rule. **Spellcasting ability.** Wisdom. Spell save DC is 8 + your Proficiency Bonus + your Wisdom modifier. Spell attack bonus is your Proficiency Bonus + your Wisdom modifier. You can use a druidic focus as a spellcasting focus."],[6,"Whispers of Beyond","If you spend one minute in contemplation when you make an Intelligence or Wisdom check, you can ask the spirits for Advantage on the roll. The GM can refuse if the spirits would have no fitting knowledge."],[13,"Spell Resistance","You have Advantage on saving throws against spells."],[20,"Ethereal Watcher","Action: for 1 minute you become a spiritual watcher. As a Bonus Action on your turn you can become ethereal, as in the Etherealness spell. You can return as a Bonus Action when you cast a spell, or when you use Warden's Mark or Warden's Grasp on your turn. When you return, each creature you choose within 10 feet takes 4d10 Force damage. You can cast level 1 and 2 Druid spells you know with no slot. Long Rest to use it again."]],"full":{"Soulblood Shaman|Soulblood":"As a Reaction when a creature within 5 feet damages you, you can mark that creature.","Soulblood Shaman|Spellcasting":"You cast Druid spells using Wisdom. **Cantrips.** Learn two Druid cantrips, and a third at level 10. **Spell slots.** The Soulblood Shaman Spellcasting table gives your slots. They return on a Long Rest. **Spells known.** You know three level 1 Druid spells, two of which must be Evocation or Transmutation. The table shows when you learn more. Each must be Evocation or Transmutation and of a level you have slots for, except those learned at levels 8, 14 and 20, which can be from any school. When you gain a Warden level you can swap one spell for another that follows the same rule. **Spellcasting ability.** Wisdom. Spell save DC is 8 + your Proficiency Bonus + your Wisdom modifier. Spell attack bonus is your Proficiency Bonus + your Wisdom modifier. You can use a druidic focus as a spellcasting focus.","Soulblood Shaman|Whispers of Beyond":"If you spend one minute in contemplation when you make an Intelligence or Wisdom check, you can ask the spirits for Advantage on the roll. The GM can refuse if the spirits would have no fitting knowledge.","Soulblood Shaman|Spell Resistance":"You have Advantage on saving throws against spells.","Soulblood Shaman|Ethereal Watcher":"Action: for 1 minute you become a spiritual watcher. As a Bonus Action on your turn you can become ethereal, as in the Etherealness spell. You can return as a Bonus Action when you cast a spell, or when you use Warden's Mark or Warden's Grasp on your turn. When you return, each creature you choose within 10 feet takes 4d10 Force damage. You can cast level 1 and 2 Druid spells you know with no slot. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Soulblood Shaman","feature":"Ethereal Watcher","n":"Ethereal Watcher","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Soulblood Shaman|Ethereal Watcher":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Soulblood",{"notes":[["Note","Soulblood: Reaction to mark a creature within 5 feet that damages you"]]}],[6,"Whispers of Beyond",{"notes":[["Note","Whispers of Beyond: one minute of contemplation gives Advantage on an Intelligence or Wisdom check (GM may refuse)"]]}]],"spab":"WIS","third":{"list":"Druid","ab":"WIS","cant":2},"gx":[{"l":13,"n":"Spell Resistance","advOn":["saving throws against spells"]}]},{"alt":[],"cls":"Warden (2014)","name":"Stoneheart Defender (2014)","src":"tvss14","arr":[[3,"Roots of Rock","When you use Warden's Grasp, rocky roots grow from your feet. Until the start of your next turn you have a +2 bonus to AC. Also, until you move, hostile actions, spells and effects cannot shove or push you from your spot unless you allow it. You have Advantage on Strength saving throws against being knocked Prone, you cannot slip or fall from ledges, and you are immune to the Fly, Levitate and Telekinesis spells."],[6,"Earthshatter","You can use Warden's Grasp as an action instead of a Bonus Action. If you do, each creature it affects makes a Strength saving throw (DC 8 + your Proficiency Bonus + your Strength modifier) or falls Prone. You can do this a number of times equal to your Strength modifier, and you regain all uses when you finish a Long Rest."],[13,"Mettle","When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Immortal Mountain","As an action you wrap yourself in stone for 1 minute. While it lasts: Bludgeoning, Piercing and Slashing damage you take is reduced by 5; you gain the effects of Roots of Rock for the whole duration; and as you move you can upend the ground, leaving a 5-foot-wide trail of difficult terrain behind you. After you use this, you cannot use it again until you finish a Long Rest."]],"full":{"Stoneheart Defender (2014)|Roots of Rock":"When you use Warden's Grasp, rocky roots grow from your feet. Until the start of your next turn you have a +2 bonus to AC. Also, until you move, hostile actions, spells and effects cannot shove or push you from your spot unless you allow it. You have Advantage on Strength saving throws against being knocked Prone, you cannot slip or fall from ledges, and you are immune to the Fly, Levitate and Telekinesis spells.","Stoneheart Defender (2014)|Earthshatter":"You can use Warden's Grasp as an action instead of a Bonus Action. If you do, each creature it affects makes a Strength saving throw (DC 8 + your Proficiency Bonus + your Strength modifier) or falls Prone. You can do this a number of times equal to your Strength modifier, and you regain all uses when you finish a Long Rest.","Stoneheart Defender (2014)|Mettle":"When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure.","Stoneheart Defender (2014)|Immortal Mountain":"As an action you wrap yourself in stone for 1 minute. While it lasts: Bludgeoning, Piercing and Slashing damage you take is reduced by 5; you gain the effects of Roots of Rock for the whole duration; and as you move you can upend the ground, leaving a 5-foot-wide trail of difficult terrain behind you. After you use this, you cannot use it again until you finish a Long Rest."},"auto":[],"lu":[{"src":"sub","owner":"Stoneheart Defender (2014)","feature":"Earthshatter","n":"Earthshatter","lvl":6,"max":"mod:STR","reset":"long","tag":"Action. Prone on a failed save"},{"src":"sub","owner":"Stoneheart Defender (2014)","feature":"Immortal Mountain","n":"Immortal Mountain","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Stoneheart Defender (2014)|Earthshatter":[["action",""]],"sub|Stoneheart Defender (2014)|Immortal Mountain":[["action",""]]},"cantrips":[],"pick":[],"fx":[[6,"Earthshatter",{"notes":[["Note","Earthshatter: Warden's Grasp as an action. Creatures in it make a Strength save or fall Prone"]]}],[13,"Mettle",{"notes":[["Note","Mettle: a successful Constitution save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Storm Sentinel (2014)","src":"tvss14","arr":[[3,"Flash from Above","While under the open sky you can use your action to call a harmless but striking bolt of lightning or peal of thunder, even with no clouds."],[3,"Thunderblast","When you hit a creature you have marked with a melee weapon attack, each creature you choose within 5 feet of the target takes 1d8 Lightning damage."],[6,"Static Burst","When you use Warden's Grasp as a Bonus Action, each creature it affects cannot take Reactions until the start of your next turn."],[13,"Evasion","When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Stormlord","You have a flying Speed equal to your Speed. As an action you can call a lightning bolt onto yourself for 1 minute. Your flying Speed doubles. You can cast Call Lightning as a Bonus Action with no slot (DC 8 + your Proficiency Bonus + your Constitution modifier), and call a bolt on later turns as a Bonus Action. Long Rest to use it again."]],"full":{"Storm Sentinel (2014)|Flash from Above":"While under the open sky you can use your action to call a harmless but striking bolt of lightning or peal of thunder, even with no clouds.","Storm Sentinel (2014)|Thunderblast":"When you hit a creature you have marked with a melee weapon attack, each creature you choose within 5 feet of the target takes 1d8 Lightning damage.","Storm Sentinel (2014)|Static Burst":"When you use Warden's Grasp as a Bonus Action, each creature it affects cannot take Reactions until the start of your next turn.","Storm Sentinel (2014)|Evasion":"When an effect lets you make a Dexterity saving throw to take half damage, you take no damage on a success and half damage on a failure.","Storm Sentinel (2014)|Stormlord":"You have a flying Speed equal to your Speed. As an action you can call a lightning bolt onto yourself for 1 minute. Your flying Speed doubles. You can cast Call Lightning as a Bonus Action with no slot (DC 8 + your Proficiency Bonus + your Constitution modifier), and call a bolt on later turns as a Bonus Action. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Storm Sentinel (2014)","feature":"Stormlord","n":"Stormlord","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Storm Sentinel (2014)|Stormlord":[["action",""]],"sub|Storm Sentinel (2014)|Flash from Above":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Thunderblast",{"notes":[["Note","Thunderblast: a melee hit on your marked creature deals 1d8 Lightning to creatures of your choice within 5 feet of it"]]}],[6,"Static Burst",{"notes":[["Note","Static Burst: creatures in a bonus-action Warden's Grasp cannot take Reactions until your next turn"]]}],[13,"Evasion",{"notes":[["Note","Evasion: a successful Dexterity save against half-damage effects means no damage"]]}]],"spab":"","gx":[{"l":20,"n":"Stormlord","mv":{"fly":"speed"}}]},{"alt":[],"cls":"Captain (2014)","name":"Treant Banner","src":"tvss14","arr":[[3,"Maneuver: Blocked Passage","As a Bonus Action, spend a battle die to block your enemies' way with natural terrain. The area is a number of unoccupied 10-foot cubes equal to the roll, arranged as you like with each cube touching another by a face. The GM chooses the terrain, such as boulders, fallen trees or gusting winds. You choose whether it is Difficult Terrain or impassable. Each cube has AC 15, 15 HP and Immunity to Poison and Psychic damage. After you use it, you cannot use it again for 1 minute."],[7,"Druidbane","You and your cohort ignore magical and nonmagical Difficult Terrain. You are immune to Spike Growth and other spells that change natural terrain, such as Hallucinatory Terrain and Plant Growth."],[13,"Superior Positioning","You and each friendly creature within 15 feet have Advantage on attack rolls against creatures standing in Difficult Terrain."],[17,"Thornfoot","When you or your cohort move over ground, you can leave a 5-foot-wide strip of thorns behind, as in Spike Growth, using your maneuver save DC. It lasts 10 minutes or until you dismiss it on your turn with no action."]],"full":{"Treant Banner|Maneuver: Blocked Passage":"As a Bonus Action, spend a battle die to block your enemies' way with natural terrain. The area is a number of unoccupied 10-foot cubes equal to the roll, arranged as you like with each cube touching another by a face. The GM chooses the terrain, such as boulders, fallen trees or gusting winds. You choose whether it is Difficult Terrain or impassable. Each cube has AC 15, 15 HP and Immunity to Poison and Psychic damage. After you use it, you cannot use it again for 1 minute.","Treant Banner|Druidbane":"You and your cohort ignore magical and nonmagical Difficult Terrain. You are immune to Spike Growth and other spells that change natural terrain, such as Hallucinatory Terrain and Plant Growth.","Treant Banner|Superior Positioning":"You and each friendly creature within 15 feet have Advantage on attack rolls against creatures standing in Difficult Terrain.","Treant Banner|Thornfoot":"When you or your cohort move over ground, you can leave a 5-foot-wide strip of thorns behind, as in Spike Growth, using your maneuver save DC. It lasts 10 minutes or until you dismiss it on your turn with no action."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[],"fx":[[7,"Druidbane",{"notes":[["Note","Druidbane: ignore Difficult Terrain. Immune to Spike Growth, Hallucinatory Terrain and Plant Growth"]]}]],"spab":""},{"alt":[],"cls":"Captain (2014)","name":"Turtle Banner","src":"tvss14","arr":[[3,"Bonus Proficiencies","You gain proficiency with heavy armor."],[3,"Maneuver: Iron Shell","As a Bonus Action, spend a battle die to fortify an ally you can see within 60 feet. For 1 minute, against the next attack made against it, the ally gains a bonus to AC equal to half the roll, rounded down (minimum +1)."],[7,"Slow and Steady","Your Speed cannot be reduced to 0 by effects, and you cannot be knocked Prone or moved against your will."],[13,"Shield Wall","You count as cover against effects passing through your space for allies of your size or smaller within 5 feet of you."],[17,"Unbreakable","You have a pool of 20 armor points. As a Reaction when a melee weapon attack hits you, spend any number of them and add them to your AC against that attack, which can make it miss. A Long Rest restores all of them."]],"full":{"Turtle Banner|Bonus Proficiencies":"You gain proficiency with heavy armor.","Turtle Banner|Maneuver: Iron Shell":"As a Bonus Action, spend a battle die to fortify an ally you can see within 60 feet. For 1 minute, against the next attack made against it, the ally gains a bonus to AC equal to half the roll, rounded down (minimum +1).","Turtle Banner|Slow and Steady":"Your Speed cannot be reduced to 0 by effects, and you cannot be knocked Prone or moved against your will.","Turtle Banner|Shield Wall":"You count as cover against effects passing through your space for allies of your size or smaller within 5 feet of you.","Turtle Banner|Unbreakable":"You have a pool of 20 armor points. As a Reaction when a melee weapon attack hits you, spend any number of them and add them to your AC against that attack, which can make it miss. A Long Rest restores all of them."},"auto":[],"lu":[{"src":"sub","owner":"Turtle Banner","feature":"Unbreakable","n":"Unbreakable","lvl":17,"max":20,"reset":"long","tag":"Armor points"}],"acts":{"sub|Turtle Banner|Unbreakable":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Bonus Proficiencies",{"armor":["Heavy"]}],[7,"Slow and Steady",{"notes":[["Note","Slow and Steady: Speed cannot be removed. Cannot be knocked Prone or moved against your will"]]}]],"spab":""},{"alt":[],"cls":"Alchemist (2014)","name":"Venomsmith (2014)","src":"tvss14","arr":[[3,"Formula: Venom Bomb","Bomb formula: Venom Bomb. It deals Poison damage instead of Fire, with d8 dice, and uses a Constitution save. The target, and each creature in the blast that fails its save, has Disadvantage on the next Strength, Dexterity or Constitution save it makes before the end of its next turn."],[3,"Poisoner","You gain the Poisoner discovery. Until level 3 you have 2 reagent dice you can spend only on poisons from it. You cannot swap this discovery later. Your Poison damage ignores Resistance to Poison, and treats Immunity to Poison as Resistance, dealing half damage."],[6,"Alchemical Assassin","You have Advantage on Dexterity (Sleight of Hand) checks to slip ingested poison into food or drink, apply poison to a weapon you hold unseen, or plant a vial of poison on someone unnoticed."],[10,"Mithridatism","You are immune to Poison damage and the Poisoned condition."],[18,"Toxic Recompense","When a creature within 5 feet hits you with a melee attack, you can use your Reaction to spray poison vapor. The attacker makes a Constitution save against your Bomb save DC or is Poisoned for 1 minute and takes 1d10 Poison damage at the start of each of its turns. It repeats the save at the end of each of its turns, ending the effect on a success."]],"full":{"Venomsmith (2014)|Formula: Venom Bomb":"Bomb formula: Venom Bomb. It deals Poison damage instead of Fire, with d8 dice, and uses a Constitution save. The target, and each creature in the blast that fails its save, has Disadvantage on the next Strength, Dexterity or Constitution save it makes before the end of its next turn.","Venomsmith (2014)|Poisoner":"You gain the Poisoner discovery. Until level 3 you have 2 reagent dice you can spend only on poisons from it. You cannot swap this discovery later. Your Poison damage ignores Resistance to Poison, and treats Immunity to Poison as Resistance, dealing half damage.","Venomsmith (2014)|Alchemical Assassin":"You have Advantage on Dexterity (Sleight of Hand) checks to slip ingested poison into food or drink, apply poison to a weapon you hold unseen, or plant a vial of poison on someone unnoticed.","Venomsmith (2014)|Mithridatism":"You are immune to Poison damage and the Poisoned condition.","Venomsmith (2014)|Toxic Recompense":"When a creature within 5 feet hits you with a melee attack, you can use your Reaction to spray poison vapor. The attacker makes a Constitution save against your Bomb save DC or is Poisoned for 1 minute and takes 1d10 Poison damage at the start of each of its turns. It repeats the save at the end of each of its turns, ending the effect on a success."},"auto":[],"lu":[],"acts":{"sub|Venomsmith (2014)|Toxic Recompense":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[2,"Poisoner",{"notes":[["Note","Poisoner: Poison damage ignores Resistance and treats Immunity as Resistance"]]}],[10,"Mithridatism",{"imm":["Poison"],"notes":[["Note","Mithridatism: immune to the Poisoned condition"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Verdant Protector (2014)","src":"tvss14","arr":[[3,"Green Mark","Plants hinder a creature you mark. While it is within 30 feet of you, the ground it walks on is Difficult Terrain."],[6,"Verdant Skin","You gain proficiency in Stealth if you lacked it. Action: draw a mass of vines and leaves over yourself. Until you move, you have Advantage on Dexterity (Stealth) checks to hide among vegetation."],[13,"Mettle","When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure."],[20,"Form of the Oak Sentinel","Action: turn into a bark-covered titan for 1 minute. Your AC becomes 20 if it was lower. Your attacks gain Reach if they lacked it. You can use Warden's Grasp as an action, and when you do you can attack each creature it affects, with a separate attack roll for each. Long Rest to use it again."]],"full":{"Verdant Protector (2014)|Green Mark":"Plants hinder a creature you mark. While it is within 30 feet of you, the ground it walks on is Difficult Terrain.","Verdant Protector (2014)|Verdant Skin":"You gain proficiency in Stealth if you lacked it. Action: draw a mass of vines and leaves over yourself. Until you move, you have Advantage on Dexterity (Stealth) checks to hide among vegetation.","Verdant Protector (2014)|Mettle":"When an effect lets you make a Constitution saving throw to take half damage, you take no damage on a success and half damage on a failure.","Verdant Protector (2014)|Form of the Oak Sentinel":"Action: turn into a bark-covered titan for 1 minute. Your AC becomes 20 if it was lower. Your attacks gain Reach if they lacked it. You can use Warden's Grasp as an action, and when you do you can attack each creature it affects, with a separate attack roll for each. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Verdant Protector (2014)","feature":"Form of the Oak Sentinel","n":"Form of the Oak Sentinel","lvl":20,"max":1,"reset":"long","tag":"Action. 1 minute"}],"acts":{"sub|Verdant Protector (2014)|Form of the Oak Sentinel":[["action",""]]},"cantrips":[],"pick":[],"fx":[[3,"Green Mark",{"notes":[["Note","Green Mark: ground within 30 ft of you is Difficult Terrain for a creature you have marked"]]}],[6,"Verdant Skin",{"skills":["Stealth"],"notes":[["Note","Verdant Skin: Action to hide among vegetation with Advantage on Stealth until you move"]]}],[13,"Mettle",{"notes":[["Note","Mettle: a successful Constitution save against half-damage effects means no damage"]]}]],"spab":""},{"alt":[],"cls":"Warden (2014)","name":"Witchbane Hunter (2014)","src":"tvss14","arr":[[3,"Witchbane Mark","You have Advantage on saving throws against the spells and effects of a creature you have marked. A marked creature has Disadvantage on Constitution saving throws to keep Concentration."],[6,"Eldritch Reflection","When you succeed on a saving throw against a spell, you can use your Reaction to cast the spell back at its caster as if it came from you, with the caster as the target. Long Rest to use it again."],[13,"Spell Resistance","You have Advantage on saving throws against spells."],[20,"Antimage","Bonus Action: become a breaker of mages, wrapped in antimagic, for 1 minute. You have Advantage on the first attack roll of each of your turns. When you use Warden's Grasp, its area becomes an antimagic field, as in the spell. You can wrap the field around creatures you choose, leaving pockets where magic still works, though magic from there cannot reach the rest of the field. Long Rest to use it again."]],"full":{"Witchbane Hunter (2014)|Witchbane Mark":"You have Advantage on saving throws against the spells and effects of a creature you have marked. A marked creature has Disadvantage on Constitution saving throws to keep Concentration.","Witchbane Hunter (2014)|Eldritch Reflection":"When you succeed on a saving throw against a spell, you can use your Reaction to cast the spell back at its caster as if it came from you, with the caster as the target. Long Rest to use it again.","Witchbane Hunter (2014)|Spell Resistance":"You have Advantage on saving throws against spells.","Witchbane Hunter (2014)|Antimage":"Bonus Action: become a breaker of mages, wrapped in antimagic, for 1 minute. You have Advantage on the first attack roll of each of your turns. When you use Warden's Grasp, its area becomes an antimagic field, as in the spell. You can wrap the field around creatures you choose, leaving pockets where magic still works, though magic from there cannot reach the rest of the field. Long Rest to use it again."},"auto":[],"lu":[{"src":"sub","owner":"Witchbane Hunter (2014)","feature":"Eldritch Reflection","n":"Eldritch Reflection","lvl":6,"max":1,"reset":"long","tag":"Reaction"},{"src":"sub","owner":"Witchbane Hunter (2014)","feature":"Antimage","n":"Antimage","lvl":20,"max":1,"reset":"long","tag":"Bonus Action. 1 minute"}],"acts":{"sub|Witchbane Hunter (2014)|Eldritch Reflection":[["reaction",""]],"sub|Witchbane Hunter (2014)|Antimage":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[3,"Witchbane Mark",{"notes":[["Note","Witchbane Mark: Advantage on saves against spells and effects of your marked creature, which has Disadvantage on concentration saves"]]}],[6,"Eldritch Reflection",{"notes":[["Note","Eldritch Reflection: Reaction after a successful save against a spell to cast it back at the caster"]]}]],"spab":"","gx":[{"l":13,"n":"Spell Resistance","advOn":["saving throws against spells"]}]},{"alt":[],"cls":"Alchemist (2014)","name":"Xenoalchemist (2014)","src":"tvss14","arr":[[3,"Mad Scientist","You gain two monstrous grafts of your choice. You lose no HP or Hit Dice from installing or removing grafts, and a new graft needs no recovery time."],[3,"Xenobiology","You have Advantage on ability checks to identify or research monsters."],[6,"Surgical Attack","When you take the Attack action or prime and throw a Bomb on your turn, you can make an Unarmed Strike as part of that action. This works only if a graft, such as Bestial Features, improves your Unarmed Strike."],[10,"Necromantic Organs","If you drop to 0 HP and are not killed outright, you can drop to 1 HP instead. Long Rest to use it again."],[18,"It's Alive","Through an 8-hour procedure (done over a Long Rest) you can build an alchemy golem. You need a healer's kit, alchemist's supplies, a knife (or a facility with such tools) and at least three recently dead Humanoid corpses. The golem acts on its own turn and always obeys you. As a Bonus Action you can command it if it is within 60 feet, choosing its action and movement, or give a general order such as guarding a corridor. With no order it only defends itself. It uses your Intelligence modifier plus your Proficiency Bonus for attack rolls. At 0 HP it dies. A Short or Long Rest restores and reanimates it. You can attach up to three grafts to it. You can have one alchemy golem at a time."]],"full":{"Xenoalchemist (2014)|Mad Scientist":"You gain two monstrous grafts of your choice. You lose no HP or Hit Dice from installing or removing grafts, and a new graft needs no recovery time.","Xenoalchemist (2014)|Xenobiology":"You have Advantage on ability checks to identify or research monsters.","Xenoalchemist (2014)|Surgical Attack":"When you take the Attack action or prime and throw a Bomb on your turn, you can make an Unarmed Strike as part of that action. This works only if a graft, such as Bestial Features, improves your Unarmed Strike.","Xenoalchemist (2014)|Necromantic Organs":"If you drop to 0 HP and are not killed outright, you can drop to 1 HP instead. Long Rest to use it again.","Xenoalchemist (2014)|It's Alive":"Through an 8-hour procedure (done over a Long Rest) you can build an alchemy golem. You need a healer's kit, alchemist's supplies, a knife (or a facility with such tools) and at least three recently dead Humanoid corpses. The golem acts on its own turn and always obeys you. As a Bonus Action you can command it if it is within 60 feet, choosing its action and movement, or give a general order such as guarding a corridor. With no order it only defends itself. It uses your Intelligence modifier plus your Proficiency Bonus for attack rolls. At 0 HP it dies. A Short or Long Rest restores and reanimates it. You can attach up to three grafts to it. You can have one alchemy golem at a time."},"auto":[],"lu":[{"src":"sub","owner":"Xenoalchemist (2014)","feature":"Necromantic Organs","n":"Necromantic Organs","lvl":10,"max":1,"reset":"long","tag":"Drop to 1 HP"}],"acts":{},"cantrips":[],"pick":[],"fx":[[2,"Xenobiology",{"notes":[["Note","Xenobiology: Advantage on checks to identify or research monsters"]]}]],"spab":""}];
